// ============================================================
// Cache Cleanup & Invalidation System
// Automatically clears old data on website load to prevent
// conflicts with updated website version
// ============================================================

export interface CacheMetadata {
  version: string;
  lastCleanup: string;
  createdAt: string;
}

// Cache keys to manage
const CACHE_KEYS = {
  DEDUP_CACHE: "tl_dedup_cache",
  SEARCH_CACHE: "tl_search_cache",
  SOURCE_HEALTH: "tl_source_health",
  FEED_CACHE: "tl_feed_cache",
  IOC_CACHE: "tl_ioc_cache",
  ONLINE_SEARCH_RESULTS: "tl_online_search_results",
  CONFIDENCE_SCORES: "tl_confidence_scores",
  THREAT_ITEMS_CACHE: "tl_threat_items_cache",
  CACHE_METADATA: "tl_cache_metadata",
};

// TTL (Time To Live) in milliseconds
const CACHE_TTL = {
  SEARCH: 30 * 60 * 1000, // 30 minutes
  DEDUP: 24 * 60 * 60 * 1000, // 24 hours
  SOURCE_HEALTH: 60 * 60 * 1000, // 1 hour
  FEED: 15 * 60 * 1000, // 15 minutes
  IOC: 24 * 60 * 60 * 1000, // 24 hours
  THREAT_ITEMS: 10 * 60 * 1000, // 10 minutes
};

// Website version - increment this to trigger cache clear on next load
const WEBSITE_VERSION = "2.1.0"; // Updated: June 9, 2026 — cache bust + auto-refresh

/**
 * Get cache metadata
 */
function getCacheMetadata(): CacheMetadata {
  try {
    const meta = localStorage.getItem(CACHE_KEYS.CACHE_METADATA);
    return meta ? JSON.parse(meta) : {
      version: WEBSITE_VERSION,
      lastCleanup: new Date().toISOString(),
      createdAt: new Date().toISOString(),
    };
  } catch {
    return {
      version: WEBSITE_VERSION,
      lastCleanup: new Date().toISOString(),
      createdAt: new Date().toISOString(),
    };
  }
}

/**
 * Save cache metadata
 */
function saveCacheMetadata(metadata: CacheMetadata): void {
  try {
    localStorage.setItem(CACHE_KEYS.CACHE_METADATA, JSON.stringify(metadata));
  } catch {
    console.warn("Failed to save cache metadata");
  }
}

/**
 * Check if data is stale (older than TTL)
 */
function isStale(timestamp: string | undefined, ttl: number): boolean {
  if (!timestamp) return true;
  try {
    const createdTime = new Date(timestamp).getTime();
    const now = new Date().getTime();
    return now - createdTime > ttl;
  } catch {
    return true;
  }
}

/**
 * Clear a specific cache key
 */
function clearCacheKey(key: string): void {
  try {
    localStorage.removeItem(key);
    console.log(`✓ Cleared cache: ${key}`);
  } catch {
    console.warn(`Failed to clear cache: ${key}`);
  }
}

/**
 * Clear all application caches
 */
export function clearAllCaches(): void {
  console.log("🧹 Clearing all caches...");
  
  Object.values(CACHE_KEYS).forEach((key) => {
    clearCacheKey(key);
  });

  // Clear browser cache storage
  try {
    if ('caches' in window) {
      caches.keys().then((names) => {
        names.forEach((name) => {
          caches.delete(name);
          console.log(`✓ Cleared browser cache: ${name}`);
        });
      });
    }
  } catch {
    console.warn("Browser cache clearing not available");
  }

  // Update metadata
  const metadata: CacheMetadata = {
    version: WEBSITE_VERSION,
    lastCleanup: new Date().toISOString(),
    createdAt: new Date().toISOString(),
  };
  saveCacheMetadata(metadata);

  console.log("✅ All caches cleared successfully");
}

/**
 * Clean up stale cache entries
 */
export function cleanupStaleCaches(): void {
  console.log("🧹 Checking for stale caches...");
  
  const metadata = getCacheMetadata();
  let cleanedCount = 0;

  // Check search cache
  try {
    const searchCache = localStorage.getItem(CACHE_KEYS.SEARCH_CACHE);
    if (searchCache) {
      const parsed = JSON.parse(searchCache);
      if (isStale(parsed.timestamp, CACHE_TTL.SEARCH)) {
        clearCacheKey(CACHE_KEYS.SEARCH_CACHE);
        cleanedCount++;
      }
    }
  } catch {
    clearCacheKey(CACHE_KEYS.SEARCH_CACHE);
    cleanedCount++;
  }

  // Check feed cache
  try {
    const feedCache = localStorage.getItem(CACHE_KEYS.FEED_CACHE);
    if (feedCache) {
      const parsed = JSON.parse(feedCache);
      if (isStale(parsed.timestamp, CACHE_TTL.FEED)) {
        clearCacheKey(CACHE_KEYS.FEED_CACHE);
        cleanedCount++;
      }
    }
  } catch {
    clearCacheKey(CACHE_KEYS.FEED_CACHE);
    cleanedCount++;
  }

  // Check threat items cache
  try {
    const threatCache = localStorage.getItem(CACHE_KEYS.THREAT_ITEMS_CACHE);
    if (threatCache) {
      const parsed = JSON.parse(threatCache);
      if (isStale(parsed.timestamp, CACHE_TTL.THREAT_ITEMS)) {
        clearCacheKey(CACHE_KEYS.THREAT_ITEMS_CACHE);
        cleanedCount++;
      }
    }
  } catch {
    clearCacheKey(CACHE_KEYS.THREAT_ITEMS_CACHE);
    cleanedCount++;
  }

  // Check online search results cache
  try {
    const resultsCache = localStorage.getItem(CACHE_KEYS.ONLINE_SEARCH_RESULTS);
    if (resultsCache) {
      const parsed = JSON.parse(resultsCache);
      if (isStale(parsed.timestamp, CACHE_TTL.SEARCH)) {
        clearCacheKey(CACHE_KEYS.ONLINE_SEARCH_RESULTS);
        cleanedCount++;
      }
    }
  } catch {
    clearCacheKey(CACHE_KEYS.ONLINE_SEARCH_RESULTS);
    cleanedCount++;
  }

  if (cleanedCount > 0) {
    console.log(`✅ Cleaned ${cleanedCount} stale cache entries`);
  } else {
    console.log("✓ No stale caches found");
  }

  // Update metadata
  metadata.lastCleanup = new Date().toISOString();
  saveCacheMetadata(metadata);
}

/**
 * Check version and clear cache if needed
 */
export function checkVersionAndCleanup(): void {
  console.log("🔍 Checking website version...");
  
  const metadata = getCacheMetadata();
  
  if (metadata.version !== WEBSITE_VERSION) {
    console.log(`⚠️  Version mismatch detected`);
    console.log(`   Old version: ${metadata.version}`);
    console.log(`   New version: ${WEBSITE_VERSION}`);
    console.log(`   Clearing all caches...`);
    
    clearAllCaches();
  } else {
    console.log(`✓ Version matches: ${WEBSITE_VERSION}`);
    cleanupStaleCaches();
  }
}

/**
 * Initialize cache cleanup on app load
 * Call this in main.tsx or App.tsx useEffect
 */
export function initializeCacheCleanup(): void {
  try {
    console.log("🚀 Initializing cache cleanup system...");
    
    // Check version and cleanup
    checkVersionAndCleanup();
    
    // Log current cache status
    const metadata = getCacheMetadata();
    console.log("📊 Cache Status:");
    console.log(`   Version: ${metadata.version}`);
    console.log(`   Last Cleanup: ${new Date(metadata.lastCleanup).toLocaleString()}`);
    console.log(`   Created At: ${new Date(metadata.createdAt).toLocaleString()}`);
    
    // Setup periodic cleanup (every 1 minute — keeps feed data fresh)
    setInterval(() => {
      cleanupStaleCaches();
    }, 60 * 1000);
    
    console.log("✅ Cache cleanup system initialized");
  } catch (error) {
    console.error("❌ Error initializing cache cleanup:", error);
  }
}

/**
 * Manual cache clear function for UI
 * Call this from Settings page or dev tools
 */
export function manualCacheClear(): {
  success: boolean;
  message: string;
  clearedItems: number;
} {
  try {
    console.log("🧹 Manual cache clear initiated by user");
    clearAllCaches();
    
    return {
      success: true,
      message: "All caches cleared successfully. Website will use fresh data on next refresh.",
      clearedItems: Object.keys(CACHE_KEYS).length,
    };
  } catch (error) {
    const message = error instanceof Error ? error.message : "Unknown error";
    console.error("❌ Manual cache clear failed:", error);
    
    return {
      success: false,
      message: `Cache clear failed: ${message}`,
      clearedItems: 0,
    };
  }
}

/**
 * Get cache statistics
 */
export function getCacheStats(): {
  totalSize: number;
  itemCount: number;
  items: { key: string; size: number; age: string | null }[];
} {
  const items: { key: string; size: number; age: string | null }[] = [];
  let totalSize = 0;

  Object.entries(CACHE_KEYS).forEach(([_, key]) => {
    try {
      const data = localStorage.getItem(key);
      if (data) {
        const size = new Blob([data]).size;
        totalSize += size;

        // Try to get age
        let age: string | null = null;
        try {
          const parsed = JSON.parse(data);
          if (parsed.timestamp) {
            const createdTime = new Date(parsed.timestamp).getTime();
            const now = new Date().getTime();
            const ageMs = now - createdTime;
            const ageMins = Math.floor(ageMs / 60000);
            age = ageMins < 60 ? `${ageMins}m` : `${Math.floor(ageMins / 60)}h`;
          }
        } catch {
          // Not JSON or no timestamp
        }

        items.push({ key, size, age });
      }
    } catch {
      // Ignore
    }
  });

  return {
    totalSize,
    itemCount: items.length,
    items,
  };
}

/**
 * Export cache statistics to console
 */
export function printCacheStats(): void {
  const stats = getCacheStats();
  console.log("📊 Cache Statistics:");
  console.log(`   Total Size: ${(stats.totalSize / 1024).toFixed(2)} KB`);
  console.log(`   Total Items: ${stats.itemCount}`);
  console.log("   Details:");
  
  stats.items.forEach(({ key, size, age }) => {
    console.log(
      `     - ${key}: ${(size / 1024).toFixed(2)} KB ${age ? `(${age} old)` : "(no timestamp)"}`
    );
  });
}
